import LensManager, { ILens, LensLayerName } from "#core/ui/lenses/lens-manager.js";

class GeneralAppealLens implements ILens {
	activeLayers = new Set<LensLayerName>(["fxs-general-appeal-layer"]);

	allowedLayers = new Set<LensLayerName>([
		"fxs-hexgrid-layer",
		"fxs-resource-layer",
		"fxs-culture-borders-layer",
		"fxs-yields-layer",
	]);

	hasLegend = true;
}

declare global {
	interface LensTypeMap {
		"fxs-general-appeal-lens": GeneralAppealLens;
	}
}

LensManager.registerLens("fxs-general-appeal-lens", new GeneralAppealLens());
